node -e "
const math = {
  pi: Math.PI,
  pow: Math.pow,
  cos: Math.cos,
  acos: Math.acos,
};

// 파라미터
const Q = 2e-9;       // m³/s
const dP = 49;        // Pa
const eta = 1.0e-3;   // Pa·s
const L_list = [3e-3, 4e-3, 5e-3];  // m
const gamma = 0.07;   // N/m
const cosTheta = Math.cos(20 * Math.PI / 180);
const rho = 1000;
const g = 9.8;
const r_orig = 1.5e-3; // m

console.log('cos(20°):', cosTheta.toFixed(6));

const results = [];
for (const L of L_list) {
  // r = (8*eta*L*Q / (pi*dP))^(1/4)
  const r = Math.pow((8 * eta * L * Q) / (Math.PI * dP), 0.25);
  const r_mm = r * 1000;
  const Q_check = (Math.PI * Math.pow(r, 4) * dP) / (8 * eta * L);
  const Q_uL_s = Q_check * 1e9;

  // 모세관 h_cap
  const h_cap = (2 * gamma * cosTheta) / (rho * g * r);
  const h_cap_mm = h_cap * 1000;
  const ok = h_cap_mm > 5;

  // 단면적 축소율
  const areaRatio = Math.pow(r / r_orig, 2) * 100;
  const reduction = 100 - areaRatio;

  results.push({ L_mm: L*1000, r_mm, Q_uL_s, h_cap_mm, ok, areaRatio, reduction });

  console.log('L=' + (L*1000) + 'mm: r=' + r_mm.toFixed(4) + 'mm, Q=' + Q_uL_s.toFixed(4) + ' µL/s, h_cap=' + h_cap_mm.toFixed(2) + 'mm, >5mm? ' + ok + ', 단면적비=' + areaRatio.toFixed(1) + '%, 축소율=' + reduction.toFixed(1) + '%');
}
"
